def supplier_type(name, country):
    n = (name or '').strip()
    if not n:
        return None
    t = first(SUPPLIER, n)
    if t:
        return t
    if country in ('colombia', 'mexico', 'dominican-republic', 'paraguay') and not _COMPANY.search(n) and 2 <= len(n.split()) <= 6 and not re.search(r'\d', n):
        return 'Individuals'
    if re.search(r'\b(ai|ki|ia)\b|\.ai\b|intelligen|analytics|machine|neural|vision|robot|bot\b|cognit|deep', n, I):
        return 'AI-first companies'
    return 'Other firms'
